import styled, { css } from 'styled-components';

const base = css`
  padding: 0.5rem 1rem;
  border-radius: 0.375rem;
  border: 1px solid transparent;
  cursor: pointer;
`;

export const Button = styled.button<{ $tone?: 'primary' | 'ghost' }>`
  ${base}
  background: ${({ $tone }) => ($tone === 'ghost' ? 'transparent' : '#2563eb')};
  color: ${({ $tone }) => ($tone === 'ghost' ? '#2563eb' : 'white')};

  &:hover { filter: brightness(0.92); }
`;

import { ThemeProvider } from 'styled-components';

const theme = {
  colors: { primary: '#2563eb', danger: '#dc2626' },
  space: (n: number) => `${n * 0.25}rem`,
};

declare module 'styled-components' {
  export interface DefaultTheme { colors: typeof theme.colors; space: typeof theme.space; }
}

export function App({ children }: { children: React.ReactNode }) {
  return <ThemeProvider theme={theme}>{children}</ThemeProvider>;
}
